  ],
  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Current law restricts residential rent increases to 5 percent per 12-month period, exempting units occupied within the past 15 years. The proposed measure removes this cap entirely, allowing landlords to raise rents by any amount provided they give 60 days' written notice.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q3",
      "answer": "Landlords and property owners benefit from the ability to set rents at market rates without restriction. Current renters bear the cost through increased exposure to higher housing expenses and potential displacement.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Landlords may raise rents to match market demand or cover increased expenses, potentially increasing property values. Developers might be more incentivized to build new rental housing if expected returns are unconstrained by rent caps. Conversely, tenants facing large rent increases may be forced to relocate.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "The measure addresses landlords' inability to raise rents beyond a fixed percentage, which property owners argue limits returns and discourages property maintenance or new construction. By repealing the cap, it allows the market to set rents, but it removes a mechanism that shielded tenants from rapid housing cost increases.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q6",
      "answer": "Landlords and property management companies gain power and discretion to dictate rent prices without a statutory limit.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q7",
      "answer": "The broader effects of rent control and its repeal are disputed. Some researchers find that rent caps protect incumbent renters from displacement but reduce the long-term supply and quality of rental housing. Others find that repealing rent limits spurs housing investment and construction but causes immediate price shocks and displacement for vulnerable renters.",
      "disputed": true
    }
  ],
